(83, 970, 'formBuilderSettings', '{\"showHeader\":true,\"showHeading\":true,\"showDescription\":true,\"formTitle\":\"EMPOWERIG PWDs WITH LOVE\",\"enableDonationGoal\":true,\"enableAutoClose\":false,\"goalType\":\"amount\",\"goalProgressType\":\"all_time\",\"goalStartDate\":\"\",\"goalEndDate\":\"\",\"designId\":\"multi-step\",\"heading\":\"SMALL THINGS CAN LEAD TO BIG CHANGES\",\"description\":\"<p>Together, let\\u2019s make the world a place where empowerment with love is not a luxury but a fundamental right for all.<\\/p>\\n<p>\\u00a0Empowering PWDs with love is not just an act of kindness; it\\u2019s a commitment to building a society that sees everyone\\u2019s potential, no matter their physical or cognitive abilities. It\\u2019s about fostering an environment where they are celebrated for who they are and not defined by their disabilities.<\\/p>\",\"primaryColor\":\"#9058D8\",\"secondaryColor\":\"#000000\",\"goalAmount\":\"700000\",\"registrationNotification\":false,\"customCss\":\"\",\"goalAchievedMessage\":\"Thank you to all our donors, we have met our fundraising goal.\",\"pageSlug\":\"empowerig-pwds-with-love\",\"receiptHeading\":\"Hey {first_name}, thanks for your donation!\",\"receiptDescription\":\"{first_name}, your contribution means a lot and will be put to good use in making a difference. We\\u2019ve sent your donation receipt to {email}.\",\"formStatus\":\"publish\",\"emailTemplateOptions\":[],\"emailOptionsStatus\":\"global\",\"emailTemplate\":\"default\",\"emailLogo\":\"\",\"emailFromName\":\"\",\"emailFromEmail\":\"\",\"formGridCustomize\":false,\"formGridRedirectUrl\":\"\",\"formGridDonateButtonText\":\"\",\"formGridHideDocumentationLink\":false,\"offlineDonationsCustomize\":false,\"offlineDonationsInstructions\":\"\",\"donateButtonCaption\":\"Donate now\",\"multiStepFirstButtonText\":\"Donate \",\"multiStepNextButtonText\":\"Continue\",\"pdfSettings\":[],\"designSettingsImageUrl\":\"http:\\/\\/localhost\\/ngo\\/wp-content\\/uploads\\/2024\\/12\\/10-ways-to-ensure-that-people-with-disabilities-in-your-workplace-enjoy-fulfilling-careers.jpg\",\"designSettingsImageAlt\":\"\",\"designSettingsImageStyle\":\"background\",\"designSettingsLogoUrl\":\"\",\"designSettingsLogoPosition\":\"left\",\"designSettingsSectionStyle\":\"default\",\"designSettingsTextFieldStyle\":\"default\",\"designSettingsImageColor\":\"\",\"designSettingsImageOpacity\":\"\",\"formExcerpt\":\"\",\"currencySwitcherSettings\":[],\"enableReceiptConfirmationPage\":false}'),
