it\":\"px\",\"size\":53,\"sizes\":[]},\"typography_font_weight\":\"900\",\"typography_line_height\":{\"unit\":\"px\",\"size\":44,\"sizes\":[]},\"text_shadow_text_shadow_type\":\"yes\",\"_animation\":\"bounceInLeft\"},\"elements\":[],\"widgetType\":\"heading\"},{\"id\":\"11de51c2\",\"elType\":\"widget\",\"settings\":{\"text_color\":\"#000000\",\"_animation\":\"bounceInLeft\",\"editor\":\"<p>Lorem ipsum dolor sit amet, consectetur adipiscing elit. .<\\/p>\",\"align\":\"center\",\"_margin\":{\"unit\":\"px\",\"top\":\"0\",\"right\":\"0\",\"bottom\":\"-33\",\"left\":\"0\",\"isLinked\":false}},\"elements\":[],\"widgetType\":\"text-editor\"}],\"isInner\":true}],\"isInner\":false},{\"id\":\"282fcb4\",\"elType\":\"container\",\"settings\":{\"flex_direction\":\"row\",\"flex_gap\":{\"unit\":\"px\",\"size\":0,\"column\":\"0\",\"row\":\"0\"},\"boxed_width\":{\"unit\":\"px\",\"size\":1006,\"sizes\":[]},\"margin\":{\"unit\":\"px\",\"top\":\"100\",\"right\":\"1\",\"bottom\":\"1\",\"left\":\"1\",\"isLinked\":false}},\"elements\":[{\"id\":\"209716f\",\"elType\":\"container\",\"settings\":{\"content_width\":\"full\",\"width\":{\"unit\":\"%\",\"size\":70,\"sizes\":[]}},\"elements\":[{\"id\":\"8c69557\",\"elType\":\"widget\",\"settings\":{\"image\":{\"url\":\"http:\\/\\/localhost\\/ngo\\/wp-content\\/uploads\\/2024\\/11\\/portrait-indian-kids-bazaar.jpg\",\"id\":49,\"size\":\"\",\"alt\":\"\",\"source\":\"library\"},\"image_size\":\"1536x1536\",\"width\":{\"unit\":\"%\",\"size\":63,\"sizes\":[]},\"image_border_radius\":{\"unit\":\"px\",\"top\":\"20\",\"right\":\"20\",\"bottom\":\"20\",\"left\":\"20\",\"isLinked\":true}},\"elements\":[],\"widgetType\":\"image\"},{\"id\":\"6c572c5\",\"elType\":\"widget\",\"settings\":{\"title\":\"LETS HELPED VIDHU AND SHALU GO TO SCHOOL\",\"align\":\"center\",\"title_color\":\"#1A1A1A\",\"typography_typography\":\"custom\",\"typography_font_family\":\"Montserrat\",\"typography_font_size\":{\"unit\":\"px\",\"size\":45,\"sizes\":[]},\"typography_font_weight\":\"900\",\"typography_line_height\":{\"unit\":\"px\",\"size\":42,\"sizes\":[]},\"_margin\":{\"unit\":\"px\",\"top\":\"30\",\"right\":\"30\",\"bottom\":\"30\",\"left\":\"30\",\"isLinked\":true}},\"elements\":[],\"widgetType\":\"heading\"},{\"id\":\"e510acb\",\"elType\":\"widget\",\"settings\":{\"editor\":\"<p>Education is the foundation of a better future, but for many children, going to school is a dream that is not always possible due to various challenges. Vidhu and Shalu are two bright young girls who live in a village where access to education is limited. They dream of going to school, learning new things, and building a future for themselves. But they need our help to make that dream a reality.<\\/p><h4>\\u00a0<\\/h4><p>Vidhu and Shalu come from families with limited resources. Their parents are hardworking but struggle to make ends meet. School fees, uniforms, books, and transportation are some of the obstacles preventing these young girls from attending school. Despite their eagerness to learn, these financial hurdles stand in their way.\\u00a0 \\u00a0 \\u00a0 \\u00a0 \\u00a0 \\u00a0 \\u00a0 \\u00a0 \\u00a0\\u00a0<\\/p><p>Education empowers individuals, families, and communities. By helping Vidhu and Shalu go to school, we\\u2019re giving them the tools they need to break the cycle of poverty. With the right resources, these young girls can achieve their dreams, improve their communities, and contribute to society in meaningful ways.<\\/p><p>\\u00a0<\\/p>\"},\"elements\":[],\"widgetType\":\"text-editor\"}],\"isInner\":true},{\"id\":\"7e3478c\",\"elType\":\"container\",\"settings\":{\"flex_direction\":\"column\",\"content_width\":\"full\",\"width\":{\"unit\":\"%\",\"size\":30}},\"elements\":[],\"isInner\":true}],\"isInner\":false}]'),
