":52.2,\"sizes\":[]},\"gap\":{\"unit\":\"px\",\"size\":16,\"sizes\":[]},\"_margin\":{\"unit\":\"px\",\"top\":\"-29\",\"right\":\"0\",\"bottom\":\"0\",\"left\":\"0\",\"isLinked\":false}},\"elements\":[],\"widgetType\":\"divider\"}],\"isInner\":true},{\"id\":\"206b87f\",\"elType\":\"container\",\"settings\":{\"flex_direction\":\"column\",\"content_width\":\"full\",\"width\":{\"unit\":\"%\",\"size\":\"50\"}},\"elements\":[{\"id\":\"4f816be\",\"elType\":\"widget\",\"settings\":{\"title\":\" I STARTED AS A \\n <span style=\\\"color:#FF00FF\\\">WEEKEND HOBBY<\\/span>\\n\",\"align\":\"center\",\"title_color\":\"#1A1A1A\",\"typography_typography\":\"custom\",\"typography_font_family\":\"Montserrat\",\"typography_font_size\":{\"unit\":\"px\",\"size\":53,\"sizes\":[]},\"typography_font_weight\":\"900\",\"typography_line_height\":{\"unit\":\"px\",\"size\":44,\"sizes\":[]},\"text_shadow_text_shadow_type\":\"yes\",\"_animation\":\"bounceInRight\"},\"elements\":[],\"widgetType\":\"heading\"},{\"id\":\"6bdd0c6\",\"elType\":\"widget\",\"settings\":{\"editor\":\"<p>Cristiano Ronaldo, often referred to as CR7, has been an influential figure both on and off the field. Known for his philanthropic efforts, he has used his fame and wealth to make a positive impact through various charitable causes.<\\/p><p><span style=\\\"font-style: inherit; font-weight: inherit; color: var( --e-global-color-text ); font-family: var( --e-global-typography-text-font-family ), Sans-serif; text-align: var(--text-align); background-color: var(--ast-global-color-5);\\\">In 2015, Ronaldo launched his own charitable organization, the <\\/span><strong style=\\\"font-style: inherit; color: var( --e-global-color-text ); font-family: var( --e-global-typography-text-font-family ), Sans-serif; text-align: var(--text-align); background-color: var(--ast-global-color-5);\\\">Cristiano Ronaldo Foundation<\\/strong><span style=\\\"font-style: inherit; font-weight: inherit; color: var( --e-global-color-text ); font-family: var( --e-global-typography-text-font-family ), Sans-serif; text-align: var(--text-align); background-color: var(--ast-global-color-5);\\\">, which focuses on helping children and young people in need, particularly in the areas of health, education, and social inclusion. The foundation works on global projects, including supporting hospitals and promoting sports initiatives to give disadvantaged children a chance at a better life.<\\/span><\\/p><p>Ronaldo\'s charitable work includes donating millions to causes such as cancer research, disaster relief efforts, and poverty alleviation. One of his most notable donations was in 2016 when he contributed \\u20ac5 million to the reconstruction of hospitals in Portugal.<\\/p>\",\"align\":\"left\",\"text_color\":\"#000000\",\"typography_typography\":\"custom\",\"typography_font_family\":\"Montserrat\",\"typography_font_weight\":\"400\"},\"elements\":[],\"widgetType\":\"text-editor\"}],\"isInner\":true}],\"isInner\":false},{\"id\":\"9b49cb0\",\"elType\":\"container\",\"settings\":{\"flex_direction\":\"row\",\"flex_gap\":{\"unit\":\"px\",\"size\":20,\"column\":\"20\",\"row\":\"0\"},\"margin\":{\"unit\":\"px\",\"top\":\"150\",\"right\":\"0\",\"bottom\":\"0\",\"left\":\"0\",\"isLinked\":false},\"background_background\":\"classic\",\"background_color\":\"#F0E1F0\",\"background_image\":{\"url\":\"\",\"id\":\"\",\"size\":\"\",\"alt\":\"\",\"source\":\"library\"},\"background_xpos\":{\"unit\":\"px\",\"size\":121,\"sizes\":[]},\"background_attachment\":\"fixed\",\"background_repeat\":\"no-repeat\",\"background_size\":\"cover\",\"background_hover_background\":\"classic\",\"padding\":{\"unit\":\"px\",\"top\":\"50\",\"right\":\"0\",\"bottom\":\"50\",\"left\":\"0\",\"isLinked\":false}},\"elements\":[{\"id\":\"6178eda\",\"elType\":\"container\",\"settings\":{\"flex_direction\":\"column\",\"content_width\":\"full\",\"width\":{\"unit\":\"%\",\"size\":\"50\"},\"flex_justify_content\":\"center\"},\"elements\":[{\"id\":\"3b620ee\",\"elType\":