osters a sense of ownership, responsibility, and shared success.<\\/p>\"},\"elements\":[],\"widgetType\":\"text-editor\"},{\"id\":\"7e47f9b\",\"elType\":\"container\",\"settings\":{\"flex_direction\":\"row\",\"flex_justify_content\":\"center\",\"flex_align_items\":\"flex-start\",\"content_width\":\"full\",\"padding\":{\"unit\":\"px\",\"top\":\"0\",\"right\":\"0\",\"bottom\":\"0\",\"left\":\"0\",\"isLinked\":false},\"animation\":\"bounceInUp\"},\"elements\":[{\"id\":\"393eefb\",\"elType\":\"widget\",\"settings\":{\"text\":\"Projects\",\"background_color\":\"#FF00FF\",\"hover_animation\":\"bob\",\"border_radius\":{\"unit\":\"px\",\"top\":\"50\",\"right\":\"50\",\"bottom\":\"50\",\"left\":\"50\",\"isLinked\":true},\"text_padding\":{\"unit\":\"px\",\"top\":\"20\",\"right\":\"60\",\"bottom\":\"20\",\"left\":\"60\",\"isLinked\":false},\"text_shadow_text_shadow_type\":\"yes\",\"button_text_color\":\"#000000\",\"button_box_shadow_box_shadow_type\":\"yes\",\"button_box_shadow_box_shadow\":{\"horizontal\":0,\"vertical\":8,\"blur\":14,\"spread\":-1,\"color\":\"#000000\"},\"link\":{\"url\":\"#http:\\/\\/localhost\\/ngo\\/index.php\\/projects\\/\",\"is_external\":\"on\",\"nofollow\":\"\",\"custom_attributes\":\"\"},\"button_background_hover_color\":\"#FAF3F3\"},\"elements\":[],\"widgetType\":\"button\"}],\"isInner\":true}],\"isInner\":true},{\"id\":\"2ba48bd\",\"elType\":\"widget\",\"settings\":{\"image\":{\"url\":\"http:\\/\\/localhost\\/ngo\\/wp-content\\/uploads\\/2024\\/12\\/Places-Where-Americans-Give-the-Most-to-Charity-2020-Edition.jpg\",\"id\":655,\"size\":\"\",\"alt\":\"\",\"source\":\"library\"},\"image_size\":\"1536x1536\",\"image_border_radius\":{\"unit\":\"px\",\"top\":\"20\",\"right\":\"20\",\"bottom\":\"20\",\"left\":\"20\",\"isLinked\":true},\"_element_width\":\"initial\",\"_element_custom_width\":{\"unit\":\"%\",\"size\":39.344},\"_flex_size\":\"none\",\"width\":{\"unit\":\"%\",\"size\":100,\"sizes\":[]},\"space\":{\"unit\":\"%\",\"size\":100,\"sizes\":[]},\"hei