\"size\":\"50\"},\"animation\":\"slideInRight\",\"padding\":{\"unit\":\"px\",\"top\":\"1\",\"right\":\"1\",\"bottom\":\"1\",\"left\":\"1\",\"isLinked\":true}},\"elements\":[{\"id\":\"2e061d7\",\"elType\":\"widget\",\"settings\":{\"title\":\" WD DECISDED  TO MAKE IT\\n <span style=\\\"color:#FF00FF\\\">BIGGER AND BETTER<\\/span>\\n\",\"align\":\"center\",\"title_color\":\"#1A1A1A\",\"typography_typography\":\"custom\",\"typography_font_family\":\"Montserrat\",\"typography_font_size\":{\"unit\":\"px\",\"size\":53,\"sizes\":[]},\"typography_font_weight\":\"900\",\"typography_line_height\":{\"unit\":\"px\",\"size\":54,\"sizes\":[]},\"text_shadow_text_shadow_type\":\"yes\",\"_animation\":\"bounceInRight\",\"_margin\":{\"unit\":\"px\",\"top\":\"-19\",\"right\":\"0\",\"bottom\":\"-20\",\"left\":\"0\",\"isLinked\":false},\"_padding\":{\"unit\":\"px\",\"top\":\"32\",\"right\":\"0\",\"bottom\":\"30\",\"left\":\"0\",\"isLinked\":false}},\"elements\":[],\"widgetType\":\"heading\"},{\"id\":\"901c09a\",\"elType\":\"widget\",\"settings\":{\"editor\":\"<p>Cristiano Ronaldo, often referred to as CR7, has been an influential figure both on and off the field. Known for his philanthropic efforts, he has used his fame and wealth to make a positive impact through various charitable causes.<\\/p><p>.Additionally, Ronaldo has been known to make anonymous donations and regularly visits hospitals and orphanages. His story isn\'t just about football; it\\u2019s about using his platform and success to help those in need. His charity work has made him a role model for fans worldwide, demonstrating the power of using fame for good.<\\/p>\",\"align\":\"left\",\"text_color\":\"#000000\",\"typography_typography\":\"custom\",\"typography_font_family\":\"Montserrat\",\"typography_font_weight\":\"400\",\"column_gap\":{\"unit\":\"px\",\"size\":0,\"sizes\":[]},\"typography_letter_spacing\":{\"unit\":\"px\",\"size\":0.4,\"sizes\":[]},\"_padding\":{\"unit\":\"px\",\"top\":\"0\",\"right\":\"0\",\"bottom\":