\":\"20\",\"left\":\"20\",\"isLinked\":true},\"align\":\"center\",\"space\":{\"unit\":\"%\",\"size\":100,\"sizes\":[]},\"height\":{\"unit\":\"px\",\"size\":500,\"sizes\":[]},\"_margin\":{\"unit\":\"px\",\"top\":\"-23\",\"right\":\"0\",\"bottom\":\"0\",\"left\":\"0\",\"isLinked\":false},\"_padding\":{\"unit\":\"px\",\"top\":\"0\",\"right\":\"-2\",\"bottom\":\"0\",\"left\":\"0\",\"isLinked\":false}},\"elements\":[],\"widgetType\":\"image\"}],\"isInner\":true},{\"id\":\"7e3478c\",\"elType\":\"container\",\"settings\":{\"flex_direction\":\"column\",\"content_width\":\"full\",\"width\":{\"unit\":\"%\",\"size\":50},\"_flex_size\":\"none\",\"_element_width\":\"initial\"},\"elements\":[{\"id\":\"9c4b4ff\",\"elType\":\"widget\",\"settings\":{\"shortcode\":\"[give_form id=\\\"788\\\"]\",\"_margin\":{\"unit\":\"px\",\"top\":\"13\",\"right\":\"0\",\"bottom\":\"-19\",\"left\":\"0\",\"isLinked\":false},\"_padding\":{\"unit\":\"px\",\"top\":\"0\",\"right\":\"0\",\"bottom\":\"-21\",\"left\":\"0\",\"isLinked\":false}},\"elements\":[],\"widgetType\":\"shortcode\"}],\"isInner\":true}],\"isInner\":false},{\"id\":\"a9029eb\",\"elType\":\"container\",\"settings\":{\"flex_direction\":\"column\",\"boxed_width\":{\"unit\":\"px\",\"size\":1220,\"sizes\":[]},\"margin\":{\"unit\":\"px\",\"top\":\"0\",\"right\":\"0\",\"bottom\":\"0\",\"left\":\"0\",\"isLinked\":false}},\"elements\":[{\"id\":\"6c572c5\",\"elType\":\"widget\",\"settings\":{\"title\":\"LETS HELPED  <span style=\\\"color:#FF00FF\\\">VIDHU AND SHALU  <\\/span>GO TO SCHOOL\",\"align\":\"center\",\"title_color\":\"#000000\",\"typography_typography\":\"custom\",\"typography_font_family\":\"Montserrat\",\"typography_font_size\":{\"unit\":\"px\",\"size\":53,\"sizes\":[]},\"typography_font_weight\":\"900\",\"typography_line_height\":{\"unit\":\"px\",\"size\":44,\"sizes\":[]},\"text_shadow_text_shadow_type\":\"yes\",\"_animation\":\"bounceInLeft\"},\"elements\":[],\"widgetType\":\"heading\"},{\"id\":\"e510acb\",\"elType\":\"widget\",\"settings\":{\"editor\":\"<p>Education is the foundation of a better future, but for many children, going to school is a dream that is not always possible due to various challenges. Vidhu and Shalu are two bright young girls who live in a village where access to education is limited. They dream of going to school, learning new things, and building a future for themselves. But they need our help to make that dream a reality.<\\/p>\\n<p>Vidhu and Shalu come from families with limited resources. Their parents are hardworking but struggle to make ends meet. School fees, uniforms, books, and transportation are some of the obstacles preventing these young girls from attending school. Despite their eagerness to learn, these financial hurdles stand in their way.\\u00a0 \\u00a0<\\/p>\\n<p>Education empowers individuals, families, and communities. By helping Vidhu and Shalu go to school, we\\u2019re giving them the tools they need to break the cycle of poverty. With the right resources, these young girls can achieve their dreams, improve their communities, and contribute to society in meaningful ways.<\\/p>\",\"align\":\"justify\",\"text_color\":\"#585656\",\"typography_typography\":\"custom\",\"typography_font_family\":\"Montserrat\",\"typography_font_weight\":\"400\",\"typography_line_height\":{\"unit\":\"px\",\"size\":20,\"sizes\":[]},\"typography_letter_spacing\":{\"unit\":\"px\",\"size\":-0.2,\"sizes\":[]},\"typography_word_spacing\":{\"unit\":\"px\",\"size\":3,\"sizes\":[]},\"_margin\":{\"unit\":\"px\",\"top\":\"0\",\"right\":\"0\",\"bottom\":\"0\",\"left\":\"0\",\"isLinked\":false},\"_padding\":{\"unit\":\"px\",\"top\":\"0\",\"right\":\"0\",\"bottom\":\"0\",\"left\":\"0\",\"isLinked\":false}},\"elements\":[],\"widgetType\":\"text-editor\"}],\"isInner\":false},{\"id\":\"7d377ab\",\"elType\":\"container\",\"settings\":{\"flex_direction\":\"column\"},\"elements\":[],\"isInner\":false}]'),
