rdles stand in their way.\\u00a0 \\u00a0<\\/p><p>Education empowers individuals, families, and communities. By helping Vidhu and Shalu go to school, we\\u2019re giving them the tools they need to break the cycle of poverty. With the right resources, these young girls can achieve their dreams, improve their communities, and contribute to society in meaningful ways.<\\/p>\",\"align\":\"justify\",\"text_color\":\"#585656\",\"typography_typography\":\"custom\",\"typography_font_family\":\"Montserrat\",\"typography_font_weight\":\"400\",\"typography_line_height\":{\"unit\":\"px\",\"size\":20,\"sizes\":[]},\"typography_letter_spacing\":{\"unit\":\"px\",\"size\":-0.2,\"sizes\":[]},\"typography_word_spacing\":{\"unit\":\"px\",\"size\":3,\"sizes\":[]},\"_margin\":{\"unit\":\"px\",\"top\":\"0\",\"right\":\"0\",\"bottom\":\"0\",\"left\":\"0\",\"isLinked\":false},\"_padding\":{\"unit\":\"px\",\"top\":\"0\",\"right\":\"0\",\"bottom\":\"0\",\"left\":\"0\",\"isLinked\":false}},\"elements\":[],\"widgetType\":\"text-editor\"}],\"isInner\":true},{\"id\":\"7e3478c\",\"elType\":\"container\",\"settings\":{\"flex_direction\":\"column\",\"content_width\":\"full\",\"width\":{\"unit\":\"%\",\"size\":49},\"_flex_size\":\"none\",\"_element_width\":\"initial\",\"animation\":\"bounceInRight\",\"min_height\":{\"unit\":\"px\",\"size\":147,\"sizes\":[]}},\"elements\":[{\"id\":\"65472df\",\"elType\":\"widget\",\"settings\":{\"shortcode\":\"[give_form id=\\\"788\\\"]\"},\"elements\":[],\"widgetType\":\"shortcode\"}],\"isInner\":true}],\"isInner\":false},{\"id\":\"a9029eb\",\"elType\":\"container\",\"settings\":{\"flex_direction\":\"column\",\"boxed_width\":{\"unit\":\"px\",\"size\":1220,\"sizes\":[]},\"margin\":{\"unit\":\"px\",\"top\":\"0\",\"right\":\"0\",\"bottom\":\"0\",\"left\":\"0\",\"isLinked\":false},\"animation\":\"bounceInUp\"},\"elements\":[],\"isInner\":false},{\"id\":\"7d377ab\",\"elType\":\"container\",\"settings\":{\"flex_direction\":\"column\"},\"elements\":[],\"isInner\":false}]'),
