:\"rand\",\"image_spacing\":\"custom\",\"image_spacing_custom\":{\"unit\":\"px\",\"size\":8,\"sizes\":[]},\"image_border_radius\":{\"unit\":\"px\",\"top\":\"10\",\"right\":\"10\",\"bottom\":\"10\",\"left\":\"10\",\"isLinked\":true},\"_margin\":{\"unit\":\"px\",\"top\":\"-13\",\"right\":\"0\",\"bottom\":\"0\",\"left\":\"0\",\"isLinked\":false},\"_padding\":{\"unit\":\"px\",\"top\":\"0\",\"right\":\"0\",\"bottom\":\"050\",\"left\":\"0\",\"isLinked\":false},\"_animation\":\"bounceInDown\",\"_transform_skew_popover_hover\":\"transform\"},\"elements\":[],\"widgetType\":\"image-gallery\"},{\"id\":\"56012bf9\",\"elType\":\"widget\",\"settings\":{\"video_type\":\"hosted\",\"youtube_url\":\"https:\\/\\/www.youtube.com\\/watch?v=XHOmBV4js_E\",\"vimeo_url\":\"https:\\/\\/vimeo.com\\/235215203\",\"dailymotion_url\":\"https:\\/\\/www.dailymotion.com\\/video\\/x6tqhqb\",\"hosted_url\":{\"url\":\"http:\\/\\/localhost\\/ngo\\/wp-content\\/uploads\\/2024\\/12\\/AQN3QSyvrrotXnrz4_EFiiZRZK8p8_5HVB-I2RmcnUVwfWbZQ_7h6WlFZxIlyb8DC_yyRMyD3iUQquL0suVMfANP.mp4\",\"id\":822,\"size\":\"\",\"alt\":\"\",\"source\":\"library\"},\"videopress_url\":\"https:\\/\\/videopress.com\\/v\\/ZCAOzTNk\",\"autoplay\":\"yes\",\"download_button\":\"yes\",\"poster\":{\"url\":\"http:\\/\\/localhost\\/ngo\\/wp-content\\/uploads\\/2024\\/12\\/download-5.jpg\",\"id\":307,\"size\":\"\",\"alt\":\"\",\"source\":\"library\"},\"_margin\":{\"unit\":\"px\",\"top\":\"0\",\"right\":\"0\",\"bottom\":\"0\",\"left\":\"0\",\"isLinked\":false},\"_padding\":{\"unit\":\"px\",\"top\":\"0\",\"right\":\"0\",\"bottom\":\"0\",\"left\":\"0\",\"isLinked\":false},\"_animation\":\"bounceInRight\"},\"elements\":[],\"widgetType\":\"video\"}],\"isInner\":true},{\"id\":\"5eb97432\",\"elType\":\"container\",\"settings\":{\"flex_direction\":\"column\",\"content_width\":\"full\",\"width\":{\"unit\":\"%\",\"size\":45},\"_flex_size\":\"none\",\"_element_width\":\"initial\",\"animation\":\"bounceInRight\",\"min_height\":{\"unit\":\"px\",\"size\":147