-while-you-care-for-others_-\\ud83c\\udf1fCaregiverSupport-SelfCare-BurnoutRelief.jpeg\"},{\"id\":898,\"url\":\"http:\\/\\/localhost\\/ngo\\/wp-content\\/uploads\\/2024\\/12\\/94aa1589-3502-4e4b-95ac-103ef36eec64.jpeg\"},{\"id\":906,\"url\":\"http:\\/\\/localhost\\/ngo\\/wp-content\\/uploads\\/2024\\/12\\/Participatiesamenleving-eist-tol-op-de-werkvloer.jpeg\"},{\"id\":882,\"url\":\"http:\\/\\/localhost\\/ngo\\/wp-content\\/uploads\\/2024\\/12\\/How-To-Be-Disabled-According-to-Stock-Photography-1.jpg\"},{\"id\":885,\"url\":\"http:\\/\\/localhost\\/ngo\\/wp-content\\/uploads\\/2024\\/12\\/Miracle-Recovery-II_-Young-Girl-Gets-Up-from-Wheelchair-and-Raises-Hands-Up-Stock-Image-Image-of-opened-clouds_-52521929.jpg\"},{\"id\":908,\"url\":\"http:\\/\\/localhost\\/ngo\\/wp-content\\/uploads\\/2024\\/12\\/Preparing-for-the-2012-Paralympics.jpeg\"}],\"thumbnail_size\":\"2048x2048\",\"gallery_columns\":\"3\",\"gallery_display_caption\":\"none\",\"gallery_rand\":\"rand\",\"image_spacing\":\"custom\",\"image_spacing_custom\":{\"unit\":\"px\",\"size\":8,\"sizes\":[]},\"image_border_radius\":{\"unit\":\"px\",\"top\":\"10\",\"right\":\"10\",\"bottom\":\"10\",\"left\":\"10\",\"isLinked\":true},\"_margin\":{\"unit\":\"px\",\"top\":\"-13\",\"right\":\"0\",\"bottom\":\"0\",\"left\":\"0\",\"isLinked\":false},\"_padding\":{\"unit\":\"px\",\"top\":\"0\",\"right\":\"0\",\"bottom\":\"050\",\"left\":\"0\",\"isLinked\":false},\"_animation\":\"bounceInDown\",\"_transform_skew_popover_hover\":\"transform\"},\"elements\":[],\"widgetType\":\"image-gallery\"}],\"isInner\":true},{\"id\":\"5eb97432\",\"elType\":\"container\",\"settings\":{\"flex_direction\":\"column\",\"content_width\":\"full\",\"width\":{\"unit\":\"%\",\"size\":45},\"_flex_size\":\"none\",\"_element_width\":\"initial\",\"animation\":\"bounceInRight\",\"min_height\":{\"unit\":\"px\",\"size\":147,\"sizes\":[]},\"flex_justify_content\":\"flex-start\",\"margin\":{\"unit\":\"px\",\"top\":\"0\",\"right\":\"0\",\"bottom\":\"0\",\"left\":