}},\"elements\":[{\"id\":\"35e396d3\",\"elType\":\"widget\",\"settings\":{\"shortcode\":\"[give_form id=\\\"788\\\"]\",\"_animation\":\"bounceInRight\",\"_transform_scale_popover\":\"transform\"},\"elements\":[],\"widgetType\":\"shortcode\"}],\"isInner\":true}],\"isInner\":false}]'),
