(8209, 981, '_elementor_data', '[{\"id\":\"29df1c28\",\"elType\":\"container\",\"settings\":{\"flex_direction\":\"row\",\"flex_gap\":{\"unit\":\"px\",\"size\":20,\"column\":\"20\",\"row\":\"0\"},\"margin\":{\"unit\":\"px\",\"top\":\"0\",\"right\":\"0\",\"bottom\":\"0\",\"left\":\"0\",\"isLinked\":false},\"background_background\":\"classic\",\"background_color\":\"#000000\",\"background_image\":{\"url\":\"http:\\/\\/localhost\\/ngo\\/wp-content\\/uploads\\/2024\\/12\\/full-shot-friends-with-basket-ball.jpg\",\"id\":921,\"size\":\"\",\"alt\":\"\",\"source\":\"library\"},\"background_xpos\":{\"unit\":\"px\",\"size\":121,\"sizes\":[]},\"background_attachment\":\"fixed\",\"background_size\":\"cover\",\"background_hover_background\":\"classic\",\"background_overlay_background\":\"classic\",\"background_overlay_color\":\"#000000\",\"background_overlay_opacity\":{\"unit\":\"px\",\"size\":0.24,\"sizes\":[]},\"background_overlay_hover_background\":\"classic\",\"background_overlay_hover_color\":\"#000000\",\"background_overlay_hover_opacity\":{\"unit\":\"px\",\"size\":0,\"sizes\":[]},\"padding\":{\"unit\":\"px\",\"top\":\"200\",\"right\":\"0\",\"bottom\":\"44\",\"left\":\"0\",\"isLinked\":false},\"background_hover_transition\":{\"unit\":\"px\",\"size\":1.1,\"sizes\":[]},\"animation\":\"fadeIn\",\"_transform_rotate_popover\":\"transform\",\"background_position\":\"center center\",\"boxed_width\":{\"unit\":\"px\",\"size\":1140,\"sizes\":[]},\"min_height\":{\"unit\":\"px\",\"size\":0,\"sizes\":[]}},\"elements\":[{\"id\":\"447b2ebe\",\"elType\":\"container\",\"settings\":{\"flex_direction\":\"column\",\"content_width\":\"full\",\"width\":{\"unit\":\"%\",\"size\":50},\"flex_justify_content\":\"center\",\"min_height\":{\"unit\":\"px\",\"size\":394,\"sizes\":[]},\"margin\":{\"unit\":\"px\",\"top\":\"0\",\"right\":\"0\",\"bottom\":\"0\",\"left\":\"0\",\"isLinked\":false},\"animation\":\"bounceInUp\"},\"elements\":[{\"id\":\"3fdadcb1\",\"elType\":\"widget\",\"settings\":{\"title\":\" GIVEING IS\\n <span style=\\\"color:#FF00FF\\\">CARING<\\/span>\\n\",\"align\":\"left\",\"title_color\":\"#FBFAFA\",\"typography_typography\":\"custom\",\"typography_font_family\":\"Montserrat\",\"typography_font_size\":{\"unit\":\"px\",\"size\":53,\"sizes\":[]},\"typography_font_weight\":\"900\",\"typography_line_height\":{\"unit\":\"px\",\"size\":44,\"sizes\":[]},\"text_shadow_text_shadow_type\":\"yes\",\"_animation\":\"bounceInLeft\"},\"elements\":[],\"widgetType\":\"heading\"},{\"id\":\"393481e3\",\"elType\":\"widget\",\"settings\":{\"text_color\":\"#000000\",\"_animation\":\"bounceInLeft\",\"editor\":\"<p>Lorem ipsum dolor sit amet, consectetur adipiscing elit. .<\\/p>\",\"align\":\"center\",\"_margin\":{\"unit\":\"px\",\"top\":\"0\",\"right\":\"0\",\"bottom\":\"-33\",\"left\":\"0\",\"isLinked\":false}},\"elements\":[],\"widgetType\":\"text-editor\"}],\"isInner\":true}],\"isInner\":false},{\"id\":\"26c2f628\",\"elType\":\"container\",\"settings\":{\"flex_direction\":\"row\",\"flex_gap\":{\"unit\":\"px\",\"size\":0,\"column\":\"0\",\"row\":\"25\",\"isLinked\":false},\"boxed_width\":{\"unit\":\"px\",\"size\":1139,\"sizes\":[]},\"margin\":{\"unit\":\"px\",\"top\":\"100\",\"right\":\"1\",\"bottom\":\"0\",\"left\":\"1\",\"isLinked\":false},\"min_height\":{\"unit\":\"px\",\"size\":252,\"sizes\":[]}},\"elements\":[{\"id\":\"5d314cb1\",\"elType\":\"container\",\"settings\":{\"content_width\":\"full\",\"width\":{\"unit\":\"%\",\"size\":64},\"min_height\":{\"unit\":\"px\",\"size\":181,\"sizes\":[]},\"margin\":{\"unit\":\"px\",\"top\":\"5\",\"right\":\"0\",\"bottom\":\"0\",\"left\":\"-44\",\"isLinked\":false},\"padding\":{\"unit\":\"px\",\"top\":\"020\",\"right\":\"0\",\"bottom\":\"50\",\"left\":\"0\",\"isLinked\":false},\"_flex_size\":\"none\",\"_element_width\":\"initial\",\"animation\":\"fadeInLeft\"},\"elements\":[{\"id\":\"5761f2dd\",\"elType\":\"widget\",\"settings\":{\"image\":{\"url\":\"http:\\/\\/localhost\\/ngo\\/wp-content\\/uploads\\/2024\\/12\\/50-Heartwarming-Photos-That-Will-Give-You-Hope.jpeg\",\"id\":897,\"size\":\"\",\"alt\":\"\",\"source\":\"library\"},\"image_size\":\"1536x1536\",\"image_border_radius\":{\"unit\":\"px\",\"top\":\"20\",\"right\":\"20\",\"bottom\":\"20\",\"left\":\"20\",\"isLinked\":true},\"image_box_shadow_box_shadow_type\":\"yes\",\"image_box_shadow_box_shadow\":{\"horizontal\":13,\"vertical\":13,\"blur\":36,\"spread\":3,\"color\":\"rgba(0, 0, 0, 0.31)\"},\"_animation\":\"bounceInLeft\"},\"elements\":[],\"widgetType\":\"image\"},{\"id\":\"ba3bed7\",\"elType\":\"widget\",\"settings\":{\"title\":\"EMPOWERING PWDs  <span style=\\\"color:#FF00FF\\\">WITH LOVE <\\/span>\",\"align\":\"center\",\"title_color\":\"#000000\",\"typography_typography\":\"custom\",\"typography_font_family\":\"Montserrat\",\"typography_font_size\":{\"unit\":\"px\",\"size\":45,\"sizes\":[]},\"typography_font_weight\":\"900\",\"typography_line_height\":{\"unit\":\"px\",\"size\":46,\"sizes\":[]},\"text_shadow_text_shadow_type\":\"yes\",\"_animation\":\"bounceInLeft\",\"typography_letter_spacing\":{\"unit\":\"px\",\"size\":2.8,\"sizes\":[]},\"typography_word_spacing\":{\"unit\":\"px\",\"size\":10,\"sizes\":[]},\"_transform_rotateZ_effect\":{\"unit\":\"px\",\"size\":89,\"sizes\":[]},\"_transform_rotate_3d\":\"yes\",\"_transform_rotateX_effect\":{\"unit\":\"px\",\"size\":113,\"sizes\":[]},\"_transform_rotateY_effect\":{\"unit\":\"px\",\"size\":-360,\"sizes\":[]},\"_transform_translateX_effect\":{\"unit\":\"px\",\"size\":1000,\"sizes\":[]},\"_transform_translateY_effect\":{\"unit\":\"px\",\"size\":0,\"sizes\":[]},\"_transform_scale_popover\":\"transform\",\"_transform_keep_proportions\":\"\",\"_transform_skew_popover\":\"transform\"},\"elements\":[],\"widgetType\":\"heading\"},{\"id\":\"4b2276c2\",\"elType\":\"widget\",\"settings\":{\"editor\":\"<p>Love is a powerful force. It\\u2019s not just about affection, but about showing respect, understanding, and care for others. For PWDs, love means seeing them as individuals with unique strengths, talents, and aspirations, rather than defining them solely by their disability.<\\/p><p>When we empower PWDs with love, we create spaces where they feel accepted and encouraged. It\'s about cultivating a culture where:<\\/p><ul><li><strong>Access to Opportunities<\\/strong>: With love comes the responsibility to ensure equal opportunities. Everyone deserves a chance to pursue their goals, whether it\'s education, employment, or social activities. Love means advocating for accessible spaces, inclusive workplaces, and education systems that cater to all needs.<\\/li><li><strong>Support and Understanding<\\/strong>: People with disabilities often face societal misconceptions or biases. By showing love, we help break these barriers, promoting empathy and understanding. This means providing emotional support, offering help when needed, and celebrating their achievements.<\\/li><li><strong>Self-Love and Confidence<\\/strong>: Empowering PWDs with love also means teaching them to love themselves. Through encouragement and support, they can build the confidence to pursue their dreams, advocate for themselves, and live independently.<\\/li><\\/ul><p>\\u00a0Empowering PWDs with love is not just an act of kindness; it\\u2019s a commitment to building a society that sees everyone\\u2019s potential, no matter their physical or cognitive abilities. It\\u2019s about fostering an environment where they are celebrated for who they are and not defined by their disabilities.<\\/p><p>Together, let\\u2019s make the world a place where empowerment with love is not a luxury but a fundamental right for all.<\\/p>\",\"text_color\":\"#585656\",\"typography_typography\":\"custom\",\"typography_font_family\":\"Montserrat\",\"typography_font_weight\":\"400\",\"typography_line_height\":{\"unit\":\"px\",\"size\":18,\"sizes\":[]},\"typography_letter_spacing\":{\"unit\":\"px\",\"size\":-0.4,\"sizes\":[]},\"typography_word_spacing\":{\"unit\":\"px\",\"size\":4,\"sizes\":[]},\"_margin\":{\"un