adding\":{\"unit\":\"px\",\"top\":\"10\",\"right\":\"10\",\"bottom\":\"10\",\"left\":\"10\",\"isLinked\":true},\"width_tablet\":{\"unit\":\"%\",\"size\":60,\"sizes\":[]},\"width_mobile\":{\"unit\":\"%\",\"size\":\"\",\"sizes\":[]},\"margin_tablet\":{\"unit\":\"px\",\"top\":\"0\",\"right\":\"0\",\"bottom\":\"0\",\"left\":\"0\",\"isLinked\":false},\"padding_tablet\":{\"unit\":\"px\",\"top\":\"0\",\"right\":\"0\",\"bottom\":\"0\",\"left\":\"0\",\"isLinked\":false}},\"elements\":[{\"id\":\"4f816be\",\"elType\":\"widget\",\"settings\":{\"title\":\" I STARTED AS A \\n <span style=\\\"color:#FF00FF\\\">WEEKEND HOBBY<\\/span>\\n\",\"align\":\"center\",\"title_color\":\"#1A1A1A\",\"typography_typography\":\"custom\",\"typography_font_family\":\"Montserrat\",\"typography_font_size\":{\"unit\":\"px\",\"size\":53,\"sizes\":[]},\"typography_font_weight\":\"900\",\"typography_line_height\":{\"unit\":\"px\",\"size\":54,\"sizes\":[]},\"text_shadow_text_shadow_type\":\"yes\",\"_animation\":\"bounceInUp\",\"_margin\":{\"unit\":\"px\",\"top\":\"-3\",\"right\":\"-3\",\"bottom\":\"-3\",\"left\":\"-3\",\"isLinked\":true}},\"elements\":[],\"widgetType\":\"heading\"},{\"id\":\"6bdd0c6\",\"elType\":\"widget\",\"settings\":{\"editor\":\"<p>Cristiano Ronaldo, often referred to as CR7, has been an influential figure both on and off the field. Known for\\u00a0 wealth to make a positive impact through various charitable causes.<\\/p><p>Ronaldo\'s charitable work includes donating millions to causes such as cancer research, disaster relief efforts, and poverty alleviation. One of his most notable donations was in 2016 when he contributed \\u20ac5 million to the reconstruction of hospitals in Portugal<\\/p><p>.Additionally, Ronaldo has been known to make anonymous donations and regularly visits hospitals and orphanages. His story isn\'t just about football; it\\u2019s about using his platform and success to help those in need. His charity work has made him a role model for fans worldwide, demonstrating the power of using fame for good.<\\/p>\",\"align\":\"left\",\"text_color\":\"#000000\",\"typography_typography\":\"custom\",\"typography_font_family\":\"Montserrat\",\"typography_font_weight\":\"400\",\"column_gap\":{\"unit\":\"px\",\"size\":0,\"sizes\":[]},\"typography_letter_spacing\":{\"unit\":\"px\",\"size\":0.4,\"sizes\":[]},\"_padding\":{\"unit\":\"px\",\"top\":\"-10\",\"right\":\"0\",\"bottom\":\"100\",\"left\":\"0\",\"isLinked\":false},\"_margin\":{\"unit\":\"px\",\"top\":\"0\",\"right\":\"0\",\"bottom\":\"0\",\"left\":\"0\",\"isLinked\":false},\"_animation\":\"bounceInUp\"},\"elements\":[],\"widgetType\":\"text-editor\"}],\"isInner\":true}],\"isInner\":false},{\"id\":\"9b49cb0\",\"elType\":\"container\",\"settings\":{\"flex_direction\":\"row\",\"flex_gap\":{\"unit\":\"px\",\"size\":20,\"column\":\"20\",\"row\":\"0\"},\"margin\":{\"unit\":\"px\",\"top\":\"150\",\"right\":\"0\",\"bottom\":\"0\",\"left\":\"0\",\"isLinked\":false},\"background_background\":\"classic\",\"background_color\":\"#F0E1F0\",\"background_image\":{\"url\":\"\",\"id\":\"\",\"size\":\"\",\"alt\":\"\",\"source\":\"library\"},\"background_xpos\":{\"unit\":\"px\",\"size\":121,\"sizes\":[]},\"background_attachment\":\"fixed\",\"background_repeat\":\"no-repeat\",\"background_size\":\"cover\",\"background_hover_background\":\"classic\",\"padding\":{\"unit\":\"px\",\"top\":\"50\",\"right\":\"0\",\"bottom\":\"50\",\"left\":\"0\",\"isLinked\":false},\"min_height_tablet\":{\"unit\":\"px\",\"size\":29,\"sizes\":[]},\"margin_tablet\":{\"unit\":\"px\",\"top\":\"100\",\"right\":\"0\",\"bottom\":\"0\",\"left\":\"0\",\"isLinked\":false},\"padding_tablet\":{\"unit\":\"px\",\"top\":\"0\",\"right\":\"20\",\"bottom\":\"0\",\"left\":\"20\",\"isLinked\":false}},\"elements\":[{\"id\":\"6178eda\",\"elType\":\"container\",\"settings\":{\"flex_direction\":\"column\",\"content_width\":\"full\",\"width\":{\"unit\":\"%\",\"size\":\"50\"},\"flex_justify_content\":\"center\",\"animation\":\"bounceInRight\"},\"el