ating the power of using fame for good.<\\/p>\",\"align\":\"left\",\"text_color\":\"#000000\",\"typography_typography\":\"custom\",\"typography_font_family\":\"Montserrat\",\"typography_font_weight\":\"400\",\"column_gap\":{\"unit\":\"px\",\"size\":0,\"sizes\":[]},\"typography_letter_spacing\":{\"unit\":\"px\",\"size\":0.4,\"sizes\":[]},\"_padding\":{\"unit\":\"px\",\"top\":\"-10\",\"right\":\"0\",\"bottom\":\"100\",\"left\":\"0\",\"isLinked\":false},\"_margin\":{\"unit\":\"px\",\"top\":\"0\",\"right\":\"0\",\"bottom\":\"0\",\"left\":\"0\",\"isLinked\":false},\"_animation\":\"bounceInUp\"},\"elements\":[],\"widgetType\":\"text-editor\"}],\"isInner\":true}],\"isInner\":false},{\"id\":\"9b49cb0\",\"elType\":\"container\",\"settings\":{\"flex_direction\":\"row\",\"flex_gap\":{\"unit\":\"px\",\"size\":20,\"column\":\"20\",\"row\":\"0\"},\"margin\":{\"unit\":\"px\",\"top\":\"150\",\"right\":\"0\",\"bottom\":\"0\",\"left\":\"0\",\"isLinked\":false},\"background_background\":\"classic\",\"background_color\":\"#F0E1F0\",\"background_image\":{\"url\":\"\",\"id\":\"\",\"size\":\"\",\"alt\":\"\",\"source\":\"library\"},\"background_xpos\":{\"unit\":\"px\",\"size\":121,\"sizes\":[]},\"background_attachment\":\"fixed\",\"background_repeat\":\"no-repeat\",\"background_size\":\"cover\",\"background_hover_background\":\"classic\",\"padding\":{\"unit\":\"px\",\"top\":\"50\",\"right\":\"0\",\"bottom\":\"50\",\"left\":\"0\",\"isLinked\":false},\"min_height_tablet\":{\"unit\":\"px\",\"size\":29,\"sizes\":[]},\"margin_tablet\":{\"unit\":\"px\",\"top\":\"100\",\"right\":\"0\",\"bottom\":\"0\",\"left\":\"0\",\"isLinked\":false},\"padding_tablet\":{\"unit\":\"px\",\"top\":\"0\",\"right\":\"20\",\"bottom\":\"0\",\"left\":\"20\",\"isLinked\":false}},\"elements\":[{\"id\":\"6178eda\",\"elType\":\"container\",\"settings\":{\"flex_direction\":\"column\",\"content_width\":\"full\",\"width\":{\"unit\":\"%\",\"size\":\"50\"},\"flex_justify_content\":\"center\",\"animation\":\"bounceInRight\"},\"el