mation\":\"bounceInLeft\",\"typography_letter_spacing\":{\"unit\":\"px\",\"size\":0,\"sizes\":[]},\"typography_word_spacing\":{\"unit\":\"px\",\"size\":18,\"sizes\":[]},\"_transform_rotateZ_effect\":{\"unit\":\"px\",\"size\":89,\"sizes\":[]},\"_transform_rotate_3d\":\"yes\",\"_transform_rotateX_effect\":{\"unit\":\"px\",\"size\":113,\"sizes\":[]},\"_transform_rotateY_effect\":{\"unit\":\"px\",\"size\":-360,\"sizes\":[]},\"_transform_translateX_effect\":{\"unit\":\"px\",\"size\":1000,\"sizes\":[]},\"_transform_translateY_effect\":{\"unit\":\"px\",\"size\":0,\"sizes\":[]},\"_transform_scale_popover\":\"transform\",\"_transform_keep_proportions\":\"\",\"_transform_skew_popover\":\"transform\",\"typography_font_size_tablet\":{\"unit\":\"px\",\"size\":52,\"sizes\":[]},\"typography_font_size_mobile\":{\"unit\":\"px\",\"size\":45,\"sizes\":[]},\"typography_line_height_mobile\":{\"unit\":\"em\",\"size\":0.9,\"sizes\":[]},\"typography_letter_spacing_mobile\":{\"unit\":\"px\",\"size\":0.3,\"sizes\":[]},\"typography_word_spacing_mobile\":{\"unit\":\"em\",\"size\":5,\"sizes\":[]}},\"elements\":[],\"widgetType\":\"heading\"},{\"id\":\"e510acb\",\"elType\":\"widget\",\"settings\":{\"editor\":\"<p>Education is the foundation of a better future, but for many children, going to school is a dream that is not always possible due to various challenges. Vidhu and Shalu are two bright young girls who live in a village where access to education is limited. They dream of going to school, learning new things, and building a future for themselves. But they need our help to make that dream a reality.<\\/p><p>Vidhu and Shalu come from families with limited resources. Their parents are hardworking but struggle to make ends meet. School fees, uniforms, books, and transportation are some of the obstacles preventing these young girls from attending school. Despite their eagerness to learn, these financial hurdles stand in their way.\\u00a0 \\u00a0<\\/p><p>Education empowers individuals, families, and communities. By helping Vidhu and Shalu go to school, we\\u2019re giving them the tools they need to break the cycle of poverty. With the right resources, these young girls can achieve their dreams, improve their communities, and contribute to society in meaningful ways.<\\/p>\",\"align\":\"justify\",\"text_color\":\"#585656\",\"typography_typography\":\"custom\",\"typography_font_family\":\"Montserrat\",\"typography_font_weight\":\"400\",\"typography_line_height\":{\"unit\":\"px\",\"size\":20,\"sizes\":[]},\"typography_letter_spacing\":{\"unit\":\"px\",\"size\":-0.2,\"sizes\":[]},\"typography_word_spacing\":{\"unit\":\"px\",\"size\":3,\"sizes\":[]},\"_margin\":{\"unit\":\"px\",\"top\":\"0\",\"right\":\"0\",\"bottom\":\"0\",\"left\":\"0\",\"isLinked\":false},\"_padding\":{\"unit\":\"px\",\"top\":\"0\",\"right\":\"0\",\"bottom\":\"0\",\"left\":\"0\",\"isLinked\":false}},\"elements\":[],\"widgetType\":\"text-editor\"},{\"id\":\"4dada9a\",\"elType\":\"widget\",\"settings\":{\"title\":\"GALLERY\",\"align\":\"left\",\"title_color\":\"#FF00FF\",\"typography_typography\":\"custom\",\"typography_font_family\":\"Montserrat\",\"typography_font_size\":{\"unit\":\"px\",\"size\":36,\"sizes\":[]},\"typography_font_weight\":\"900\",\"typography_line_height\":{\"unit\":\"px\",\"size\":46,\"sizes\":[]},\"text_shadow_text_shadow_type\":\"yes\",\"_animation\":\"bounceInLeft\",\"typography_letter_spacing\":{\"unit\":\"px\",\"size\":0,\"sizes\":[]},\"typography_word_spacing\":{\"unit\":\"px\",\"size\":18,\"sizes\":[]},\"_margin\":{\"unit\":\"px\",\"top\":\"0\",\"right\":\"0\",\"bottom\":\"0\",\"left\":\"0\",\"isLinked\":false},\"_padding\":{\"unit\":\"px\",\"top\":\"11\",\"right\":\"0\",\"bottom\":\"0\",\"left\":\"0\",\"isLinked\":false}},\"elements\":[],\"widgetType\":\"heading\"},{\"id\":\"a5cef62\",\"elType\":\"widget\",\"settings\":{\"wp_gallery\":[{\"id\":67,\"url\":\"http:\\/\\/localhost\\/ngo\\/wp-content\\/uploads\\/2024\\/11\\/istockphoto-508222956-1024x1024-2.jpg\"},{\"id\