their way.\\u00a0 \\u00a0<\\/p><p>Education empowers individuals, families, and communities. By helping Vidhu and Shalu go to school, we\\u2019re giving them the tools they need to break the cycle of poverty. With the right resources, these young girls can achieve their dreams, improve their communities, and contribute to society in meaningful ways.<\\/p>\",\"align\":\"justify\",\"text_color\":\"#585656\",\"typography_typography\":\"custom\",\"typography_font_family\":\"Montserrat\",\"typography_font_weight\":\"400\",\"typography_line_height\":{\"unit\":\"px\",\"size\":20,\"sizes\":[]},\"typography_letter_spacing\":{\"unit\":\"px\",\"size\":-0.2,\"sizes\":[]},\"typography_word_spacing\":{\"unit\":\"px\",\"size\":3,\"sizes\":[]},\"_margin\":{\"unit\":\"px\",\"top\":\"0\",\"right\":\"0\",\"bottom\":\"0\",\"left\":\"0\",\"isLinked\":false},\"_padding\":{\"unit\":\"px\",\"top\":\"0\",\"right\":\"0\",\"bottom\":\"0\",\"left\":\"0\",\"isLinked\":false}},\"elements\":[],\"widgetType\":\"text-editor\"},{\"id\":\"4dada9a\",\"elType\":\"widget\",\"settings\":{\"title\":\"GALLERY\",\"align\":\"left\",\"title_color\":\"#FF00FF\",\"typography_typography\":\"custom\",\"typography_font_family\":\"Montserrat\",\"typography_font_size\":{\"unit\":\"px\",\"size\":36,\"sizes\":[]},\"typography_font_weight\":\"900\",\"typography_line_height\":{\"unit\":\"px\",\"size\":46,\"sizes\":[]},\"text_shadow_text_shadow_type\":\"yes\",\"_animation\":\"bounceInLeft\",\"typography_letter_spacing\":{\"unit\":\"px\",\"size\":0,\"sizes\":[]},\"typography_word_spacing\":{\"unit\":\"px\",\"size\":18,\"sizes\":[]},\"_margin\":{\"unit\":\"px\",\"top\":\"0\",\"right\":\"0\",\"bottom\":\"0\",\"left\":\"0\",\"isLinked\":false},\"_padding\":{\"unit\":\"px\",\"top\":\"11\",\"right\":\"0\",\"bottom\":\"0\",\"left\":\"0\",\"isLinked\":false}},\"elements\":[],\"widgetType\":\"heading\"},{\"id\":\"a5cef62\",\"elType\":\"widget\",\"settings\":{\"wp_gallery\":[{\"id\":67,\"url\":\"http:\\/\\/localhost\\/ngo\\/wp-con