x1024-2.jpg\" alt=\"\" aria-describedby=\"gallery-1-67\" decoding=\"async\" /></a>\n				<figcaption class=\'wp-caption-text gallery-caption\' id=\'gallery-1-67\'>\n				Wood burning stove\n				</figcaption></figure><figure class=\'gallery-item\'>\n				<a data-elementor-open-lightbox=\"yes\" data-elementor-lightbox-slideshow=\"8935efa\" data-elementor-lightbox-title=\"Indian Rural boy Having Food\" data-e-action-hash=\"#elementor-action%3Aaction%3Dlightbox%26settings%3DeyJpZCI6NTYsInVybCI6Imh0dHA6XC9cL2xvY2FsaG9zdFwvbmdvXC93cC1jb250ZW50XC91cGxvYWRzXC8yMDI0XC8xMVwvaXN0b2NrcGhvdG8tMTc1NjAwNjA3LTEwMjR4MTAyNC0xLmpwZyIsInNsaWRlc2hvdyI6Ijg5MzVlZmEifQ%3D%3D\" href=\'http://localhost/ngo/wp-content/uploads/2024/11/istockphoto-175600607-1024x1024-1.jpg\'><img width=\"1024\" height=\"680\" src=\"http://localhost/ngo/wp-content/uploads/2024/11/istockphoto-175600607-1024x1024-1.jpg\" alt=\"\" aria-describedby=\"gallery-1-56\" decoding=\"async\" /></a>\n				<figcaption class=\'wp-caption-text gallery-caption\' id=\'gallery-1-56\'>\n				Indian Rural boy Having Food\n				</figcaption></figure>\n		http://localhost/ngo/wp-content/uploads/2024/12/AQN3QSyvrrotXnrz4_EFiiZRZK8p8_5HVB-I2RmcnUVwfWbZQ_7h6WlFZxIlyb8DC_yyRMyD3iUQquL0suVMfANP.mp4[give_form id=\"788\"]', 'EMPOWERING PWDs WITH LOVE', 'People with Disabilities (PWDs) face unique challenges every day, but with the right support, love, and empowerment, they can overcome obstacles and achieve greatness. Empowering PWDs with Love is about creating a world where everyone, regardless of their abilities, is given the tools, opportunities, and respect they deserve to thrive.', 'inherit', 'closed', 'closed', '', '341-revision-v1', '', '', '2024-12-08 06:07:40', '2024-12-08 06:07:40', '', 341, 'http://localhost/ngo/?p=952', 0, 'revision', '', 0),
