data-elementor-open-lightbox=\"yes\" data-elementor-lightbox-slideshow=\"8935efa\" data-elementor-lightbox-title=\"What is the Most Comfortable Manual Wheelchair_\" data-e-action-hash=\"#elementor-action%3Aaction%3Dlightbox%26settings%3DeyJpZCI6OTIwLCJ1cmwiOiJodHRwOlwvXC9sb2NhbGhvc3RcL25nb1wvd3AtY29udGVudFwvdXBsb2Fkc1wvMjAyNFwvMTJcL1doYXQtaXMtdGhlLU1vc3QtQ29tZm9ydGFibGUtTWFudWFsLVdoZWVsY2hhaXJfLmpwZWciLCJzbGlkZXNob3ciOiI4OTM1ZWZhIn0%3D\" href=\'http://localhost/ngo/wp-content/uploads/2024/12/What-is-the-Most-Comfortable-Manual-Wheelchair_.jpeg\'><img width=\"735\" height=\"490\" src=\"http://localhost/ngo/wp-content/uploads/2024/12/What-is-the-Most-Comfortable-Manual-Wheelchair_.jpeg\" alt=\"\" decoding=\"async\" /></a>\n			</figure><figure class=\'gallery-item\'>\n				<a data-elementor-open-lightbox=\"yes\" data-elementor-lightbox-slideshow=\"8935efa\" data-elementor-lightbox-title=\"Turismo Inclusivo pt1\" data-e-action-hash=\"#elementor-action%3Aaction%3Dlightbox%26settings%3DeyJpZCI6OTE3LCJ1cmwiOiJodHRwOlwvXC9sb2NhbGhvc3RcL25nb1wvd3AtY29udGVudFwvdXBsb2Fkc1wvMjAyNFwvMTJcL1R1cmlzbW8tSW5jbHVzaXZvLXB0MS5qcGVnIiwic2xpZGVzaG93IjoiODkzNWVmYSJ9\" href=\'http://localhost/ngo/wp-content/uploads/2024/12/Turismo-Inclusivo-pt1.jpeg\'><img width=\"732\" height=\"400\" src=\"http://localhost/ngo/wp-content/uploads/2024/12/Turismo-Inclusivo-pt1.jpeg\" alt=\"\" decoding=\"async\" /></a>\n			</figure><figure class=\'gallery-item\'>\n				<a data-elementor-open-lightbox=\"yes\" data-elementor-lightbox-slideshow=\"8935efa\" data-elementor-lightbox-title=\"94aa1589-3502-4e4b-95ac-103ef36eec64\" data-e-action-hash=\"#elementor-action%3Aaction%3Dlightbox%26settings%3DeyJpZCI6ODk4LCJ1cmwiOiJodHRwOlwvXC9sb2NhbGhvc3RcL25nb1wvd3AtY29udGVudFwvdXBsb2Fkc1wvMjAyNFwvMTJcLzk0YWExNTg5LTM1MDItNGU0Yi05NWFjLTEwM2VmMzZlZWM2NC5qcGVnIiwic2xpZGVzaG93IjoiODkzNWVmYSJ9\" href=\'http://localhost/ngo/wp-content/uploads/2024/12/94aa1589-3502-4e4b-95ac-103ef36eec64.jpeg\'><img width=\"720\" height=\"480\" src=\"http://localhost/ngo/wp-content/uploads/2024/12/94aa1589-3502-4e4b-95ac-103ef36eec64.jpeg\" alt=\"\" decoding=\"async\" /></a>\n			</figure>\n[give_form id=\"970\"]', 'EMPOWERING PWDs WITH LOVE', 'People with Disabilities (PWDs) face unique challenges every day, but with the right support, love, and empowerment, they can overcome obstacles and achieve greatness. Empowering PWDs with Love is about creating a world where everyone, regardless of their abilities, is given the tools, opportunities, and respect they deserve to thrive.', 'inherit', 'closed', 'closed', '', '341-revision-v1', '', '', '2024-12-11 14:31:32', '2024-12-11 14:31:32', '', 341, 'http://localhost/ngo/?p=1550', 0, 'revision', '', 0);
